package ajv

import (
	"math"
	"strings"

	"github.com/ajv-validator/ajv-go/internal/js"
)

// This file reproduces the JavaScript operators the code generated by Ajv relies on: typeof,
// truthiness, ===, ==, String(x), +x, the relational operators and property access through the
// prototype chain of plain objects, arrays and primitives.

// undefined is the JavaScript undefined value.
var undefined = js.Undefined

// isUndefined reports whether v is undefined.
func isUndefined(v any) bool { return js.IsUndefined(v) }

// protoFunc is a function inherited from a JavaScript prototype, such as Object.prototype.toString.
// It is what `data.toString` evaluates to for a plain object without an own toString property.
type protoFunc struct{ name string }

var (
	objectCtor = protoFunc{"Object"}
	arrayCtor  = protoFunc{"Array"}
)

// Own property names of the prototypes in V8 (Node.js 24).
var (
	objectProtoNames = toSet("constructor", "__defineGetter__", "__defineSetter__", "hasOwnProperty",
		"__lookupGetter__", "__lookupSetter__", "isPrototypeOf", "propertyIsEnumerable", "toString",
		"valueOf", "__proto__", "toLocaleString")
	arrayProtoNames = toSet("length", "constructor", "at", "concat", "copyWithin", "fill", "find",
		"findIndex", "findLast", "findLastIndex", "lastIndexOf", "pop", "push", "reverse", "shift",
		"unshift", "slice", "sort", "splice", "includes", "indexOf", "join", "keys", "entries", "values",
		"forEach", "filter", "flat", "flatMap", "map", "every", "some", "reduce", "reduceRight",
		"toReversed", "toSorted", "toSpliced", "with", "toLocaleString", "toString")
	stringProtoNames = toSet("length", "constructor", "anchor", "at", "big", "blink", "bold", "charAt",
		"charCodeAt", "codePointAt", "concat", "endsWith", "fontcolor", "fontsize", "fixed", "includes",
		"indexOf", "isWellFormed", "italics", "lastIndexOf", "link", "localeCompare", "match", "matchAll",
		"normalize", "padEnd", "padStart", "repeat", "replace", "replaceAll", "search", "slice", "small",
		"split", "strike", "sub", "substr", "substring", "sup", "startsWith", "toString", "toWellFormed",
		"trim", "trimStart", "trimLeft", "trimEnd", "trimRight", "toLocaleLowerCase", "toLocaleUpperCase",
		"toLowerCase", "toUpperCase", "valueOf")
	numberProtoNames  = toSet("constructor", "toExponential", "toFixed", "toPrecision", "toString", "valueOf", "toLocaleString")
	booleanProtoNames = toSet("constructor", "toString", "valueOf")
)

func toSet(names ...string) map[string]bool {
	m := make(map[string]bool, len(names))
	for _, n := range names {
		m[n] = true
	}
	return m
}

// inObjectProto reports whether key is a property of Object.prototype, so that looking it up on
// any plain object (including Ajv's internal dictionaries) yields a truthy value.
func inObjectProto(key string) bool { return objectProtoNames[key] }

// objectProtoValue is the value of the inherited property key of a plain object.
func objectProtoValue(key string) any {
	switch key {
	case "constructor":
		return objectCtor
	case "__proto__":
		return NewObject()
	}
	return protoFunc{"Object.prototype." + key}
}

// asNumber returns v as a float64 when it is a Go number.
func asNumber(v any) (float64, bool) {
	switch x := v.(type) {
	case float64:
		return x, true
	case int:
		return float64(x), true
	case int64:
		return float64(x), true
	case int32:
		return float64(x), true
	case float32:
		return float64(x), true
	case uint:
		return float64(x), true
	case uint64:
		return float64(x), true
	case uint32:
		return float64(x), true
	case int16:
		return float64(x), true
	case int8:
		return float64(x), true
	case uint16:
		return float64(x), true
	case uint8:
		return float64(x), true
	}
	return 0, false
}

// typeOf is the typeof operator.
func typeOf(v any) string {
	switch v.(type) {
	case nil, *Object, []any:
		return "object"
	case bool:
		return "boolean"
	case string:
		return "string"
	case protoFunc, *ValidateFunction:
		return "function"
	}
	if isUndefined(v) {
		return "undefined"
	}
	if _, ok := asNumber(v); ok {
		return "number"
	}
	return "object"
}

// isArray is Array.isArray.
func isArray(v any) bool {
	_, ok := v.([]any)
	return ok
}

// isPlainObject reports whether v is a non-null object that is not an array.
func isPlainObject(v any) bool {
	o, ok := v.(*Object)
	return ok && o != nil
}

// truthy is ToBoolean.
func truthy(v any) bool {
	switch x := v.(type) {
	case nil:
		return false
	case bool:
		return x
	case string:
		return x != ""
	case *Object:
		return x != nil
	}
	if isUndefined(v) {
		return false
	}
	if n, ok := asNumber(v); ok {
		return n != 0 && !math.IsNaN(n)
	}
	return true
}

// strictEquals is the === operator. Arrays and objects are equal only when they are the same
// object; two arrays are taken to be the same object when they share their first element's
// storage and length.
func strictEquals(a, b any) bool {
	if an, ok := asNumber(a); ok {
		bn, ok := asNumber(b)
		return ok && an == bn
	}
	switch x := a.(type) {
	case nil:
		return b == nil
	case bool:
		y, ok := b.(bool)
		return ok && x == y
	case string:
		y, ok := b.(string)
		return ok && x == y
	case *Object:
		y, ok := b.(*Object)
		return ok && x == y
	case []any:
		y, ok := b.([]any)
		return ok && sameArray(x, y)
	case protoFunc:
		y, ok := b.(protoFunc)
		return ok && x == y
	case *ValidateFunction:
		y, ok := b.(*ValidateFunction)
		return ok && x == y
	}
	return isUndefined(a) && isUndefined(b)
}

func sameArray(x, y []any) bool {
	if len(x) != len(y) || cap(x) != cap(y) {
		return false
	}
	if cap(x) == 0 {
		return x == nil && y == nil
	}
	return &x[:1][0] == &y[:1][0]
}

// looseEquals is the == operator for the operand types generated code compares.
func looseEquals(a, b any) bool {
	if (a == nil || isUndefined(a)) && (b == nil || isUndefined(b)) {
		return true
	}
	if a == nil || isUndefined(a) || b == nil || isUndefined(b) {
		return false
	}
	ta, tb := typeOf(a), typeOf(b)
	if ta == tb {
		return strictEquals(a, b)
	}
	if ta == "boolean" {
		return looseEquals(toNumber(a), b)
	}
	if tb == "boolean" {
		return looseEquals(a, toNumber(b))
	}
	if (ta == "number" && tb == "string") || (ta == "string" && tb == "number") {
		return toNumber(a) == toNumber(b)
	}
	if ta == "object" || ta == "function" {
		return looseEquals(toPrimitive(a), b)
	}
	if tb == "object" || tb == "function" {
		return looseEquals(a, toPrimitive(b))
	}
	return false
}

// toPrimitive is ToPrimitive with the default hint for the values generated code handles.
func toPrimitive(v any) any {
	switch v.(type) {
	case *Object, []any, protoFunc, *ValidateFunction:
		return toString(v)
	}
	return v
}

// toString is String(v).
func toString(v any) string {
	switch x := v.(type) {
	case nil:
		return "null"
	case bool:
		if x {
			return "true"
		}
		return "false"
	case string:
		return x
	case *Object:
		return "[object Object]"
	case []any:
		parts := make([]string, len(x))
		for i, e := range x {
			if e == nil || isUndefined(e) {
				continue
			}
			parts[i] = toString(e)
		}
		return strings.Join(parts, ",")
	case protoFunc:
		name := x.name
		if i := strings.LastIndexByte(name, '.'); i >= 0 {
			name = name[i+1:]
		}
		return "function " + name + "() { [native code] }"
	case *ValidateFunction:
		return "function validate() { [code] }"
	}
	if isUndefined(v) {
		return "undefined"
	}
	if n, ok := asNumber(v); ok {
		return js.NumberToString(n)
	}
	return ""
}

// toNumber is the unary + operator.
func toNumber(v any) float64 {
	if n, ok := asNumber(v); ok {
		return n
	}
	switch x := v.(type) {
	case nil:
		return 0
	case bool:
		if x {
			return 1
		}
		return 0
	case string:
		return js.ToNumber(x)
	case []any, *Object, protoFunc, *ValidateFunction:
		return js.ToNumber(toString(x))
	}
	return math.NaN()
}

// relOp is a relational operator.
type relOp int

const (
	opLT relOp = iota
	opLTE
	opGT
	opGTE
)

// compare evaluates `a op b` with the abstract relational comparison.
func compare(a any, op relOp, b any) bool {
	pa, pb := toPrimitive(a), toPrimitive(b)
	sa, aStr := pa.(string)
	sb, bStr := pb.(string)
	if aStr && bStr {
		c := js.Compare(sa, sb)
		switch op {
		case opLT:
			return c < 0
		case opLTE:
			return c <= 0
		case opGT:
			return c > 0
		default:
			return c >= 0
		}
	}
	x, y := toNumber(pa), toNumber(pb)
	switch op {
	case opLT:
		return x < y
	case opLTE:
		return x <= y
	case opGT:
		return x > y
	default:
		return x >= y
	}
}

// propertyKey is ToPropertyKey for the key values generated code uses (strings and numbers).
func propertyKey(key any) string {
	if s, ok := key.(string); ok {
		return s
	}
	return toString(key)
}

// getProp is the member expression obj[key].
func getProp(obj, key any) any {
	switch o := obj.(type) {
	case *Object:
		if o == nil {
			return undefined
		}
		k := propertyKey(key)
		if v, ok := o.Get(k); ok {
			return v
		}
		if inObjectProto(k) {
			return objectProtoValue(k)
		}
		return undefined
	case []any:
		if n, ok := asNumber(key); ok {
			if n >= 0 && n == math.Trunc(n) && n < float64(len(o)) {
				return o[int(n)]
			}
			return undefined
		}
		k := propertyKey(key)
		if i, ok := js.ArrayIndex(k); ok {
			if int(i) < len(o) {
				return o[i]
			}
			return undefined
		}
		if k == "length" {
			return float64(len(o))
		}
		if k == "constructor" {
			return arrayCtor
		}
		if arrayProtoNames[k] {
			return protoFunc{"Array.prototype." + k}
		}
		if inObjectProto(k) {
			return objectProtoValue(k)
		}
		return undefined
	case string:
		k := propertyKey(key)
		if i, ok := js.ArrayIndex(k); ok {
			if int(i) < js.Len(o) {
				return js.CharAt(o, int(i))
			}
			return undefined
		}
		if k == "length" {
			return float64(js.Len(o))
		}
		if stringProtoNames[k] {
			return protoFunc{"String.prototype." + k}
		}
		if inObjectProto(k) {
			return objectProtoValue(k)
		}
		return undefined
	case bool:
		k := propertyKey(key)
		if booleanProtoNames[k] {
			return protoFunc{"Boolean.prototype." + k}
		}
		if inObjectProto(k) {
			return objectProtoValue(k)
		}
		return undefined
	}
	if _, ok := asNumber(obj); ok {
		k := propertyKey(key)
		if numberProtoNames[k] {
			return protoFunc{"Number.prototype." + k}
		}
		if inObjectProto(k) {
			return objectProtoValue(k)
		}
	}
	return undefined
}

// hasOwnProperty is Object.prototype.hasOwnProperty.call(obj, key).
func hasOwnProperty(obj, key any) bool {
	switch o := obj.(type) {
	case *Object:
		return o.has(propertyKey(key))
	case []any:
		k := propertyKey(key)
		if i, ok := js.ArrayIndex(k); ok {
			return int(i) < len(o)
		}
		return k == "length"
	case string:
		k := propertyKey(key)
		if i, ok := js.ArrayIndex(k); ok {
			return int(i) < js.Len(o)
		}
		return k == "length"
	}
	return false
}

// setProp is the assignment obj[key] = v.
func setProp(obj, key, v any) {
	switch o := obj.(type) {
	case *Object:
		k := propertyKey(key)
		if k == "__proto__" && !o.has(k) {
			// Assigning to __proto__ changes the prototype (ignored for primitives) instead of
			// creating an own property.
			return
		}
		o.Set(k, v)
	case []any:
		if n, ok := asNumber(key); ok && n >= 0 && n == math.Trunc(n) && n < float64(len(o)) {
			o[int(n)] = v
			return
		}
		if i, ok := js.ArrayIndex(propertyKey(key)); ok && int(i) < len(o) {
			o[i] = v
		}
	}
}

// deleteProp is the delete operator.
func deleteProp(obj, key any) {
	switch o := obj.(type) {
	case *Object:
		o.Delete(propertyKey(key))
	case []any:
		if i, ok := js.ArrayIndex(propertyKey(key)); ok && int(i) < len(o) {
			o[i] = undefined
		}
	}
}

// objectKeys is Object.keys(v) for the values it is called on.
func objectKeys(v any) []string {
	switch o := v.(type) {
	case *Object:
		return o.Keys()
	case []any:
		keys := make([]string, len(o))
		for i := range o {
			keys[i] = js.NumberToString(float64(i))
		}
		return keys
	case string:
		n := js.Len(o)
		keys := make([]string, n)
		for i := range n {
			keys[i] = js.NumberToString(float64(i))
		}
		return keys
	}
	return []string{}
}

// ucs2length counts the code points of s, as Ajv's runtime/ucs2length does.
func ucs2length(s string) int {
	units := js.CodeUnits(s)
	length := 0
	for pos := 0; pos < len(units); {
		length++
		value := units[pos]
		pos++
		if value >= 0xd800 && value <= 0xdbff && pos < len(units) {
			if units[pos]&0xfc00 == 0xdc00 {
				pos++
			}
		}
	}
	return length
}

// isNaNValue is the global isNaN.
func isNaNValue(v any) bool { return math.IsNaN(toNumber(v)) }

// isFiniteValue is the global isFinite.
func isFiniteValue(v any) bool {
	n := toNumber(v)
	return !math.IsNaN(n) && !math.IsInf(n, 0)
}
